function beginOgiriReveal(r:Room,order:string[]){const g=r.miniGame;g.revealOrder=order.filter(uid=>!!g.answers?.[uid]);g.revealIndex=0;g.revealPublished??={};r.phase='ogiri-reveal';r.deadline=null;r.remaining=0;advanceOgiriReveal(r)}
