export const tickRooms=onSchedule('every 1 minutes',async()=>{
 const [snapshot,presenceSnapshot,roomSignalSnapshot]=await Promise.all([db.ref('rooms').get(),db.ref('roomPresence').get(),db.ref('roomSignals').get()]),now=Date.now(),allPresence=(presenceSnapshot.val()||{}) as Record<string,Record<string,number>>;for(const [code,signal] of Object.entries(roomSignalSnapshot.val()||{}) as [string,any][])if(Number(signal?.closedAt)>0&&now-Number(signal.closedAt)>=10*60*1000)await db.ref(`roomSignals/${code}`).remove().catch(()=>{});
 for(const [code,raw] of Object.entries(snapshot.val()||{}) as [string,Room][]){
  const r=normalize(raw),created=Number(r.created),endedAt=Number(r.endedAt||r.startedAt||r.created||0),presence=allPresence[code]||{};
  const waiting=r.phase==='waiting',finished=['ended','ranking'].includes(r.phase)||r.phase==='wordwolf-result'||r.phase==='survey-results'&&!!r.miniGame?.finished||r.phase==='ogiri-result'&&!!r.miniGame?.finished;
  const seen=(uid:string,p:Player)=>p.connected&&now-lastSeenAt(presence,uid,p.lastSeen)<=15000;
  const noPlayersOnline=Object.values(r.players).every(p=>!seen(p.uid,p))&&now-lastSeenAt(presence,managerUid(r),r.managerLastSeen||r.players[managerUid(r)]?.lastSeen)>15000;
  const active=!waiting&&!finished,disconnectedTooLong=active&&!!r.allDisconnectedAt&&now-Number(r.allDisconnectedAt)>=10*60*1000;
  const deleteFinished=finished&&!!endedAt&&now-endedAt>=10*60*1000;
  const deleteAbandoned=waiting&&Number.isFinite(created)&&now-created>=5*60*1000&&noPlayersOnline;
  if(deleteFinished||deleteAbandoned||disconnectedTooLong){
   const reason=deleteFinished?'finished':deleteAbandoned?'abandoned':'all-disconnected';
   try{
    const ref=db.ref(`rooms/${code}`),prefetch=await ref.get();
    if(!prefetch.exists()){
     await db.ref(`roomPresence/${code}`).remove();
     await db.ref(`roomSignals/${code}`).remove();
     continue;
    }
    const initial=prefetch.val(),deletion=await ref.transaction((raw:any)=>{
     // RTDB transactions may first invoke the updater with null when this child
     // is not cached, even though the preceding rooms scan found it. Seed from
     // the per-room read; a concurrent change is still rechecked by RTDB.
     const current=raw??initial;
     if(!current)return undefined;
     const currentFinished=['ended','ranking'].includes(current.phase),currentWaiting=current.phase==='waiting',currentActive=!currentFinished&&!currentWaiting;
     const threshold=currentFinished?Number(current.endedAt||current.startedAt||current.created||0):Number(current.created||0),limit=currentFinished?10*60*1000:5*60*1000;
     const stillOffline=Object.entries(current.players||{}).every(([id,p]:[string,any])=>!p.connected||now-lastSeenAt(presence,id,p.lastSeen)>15000)&&now-lastSeenAt(presence,managerUid(current as Room),current.managerLastSeen||current.created)>15000;
     const expired=currentActive?!!current.allDisconnectedAt&&now-Number(current.allDisconnectedAt)>=10*60*1000:now-threshold>=limit&&(currentFinished||stillOffline);
     return expired?null:undefined;
    });
    if(deletion.committed&&!deletion.snapshot.exists()){
     await db.ref(`roomPresence/${code}`).remove();
     await db.ref(`roomSignals/${code}`).remove();
     logInfo('tickRooms deleted expired room',{code,phase:r.phase,reason});
    }else{
     logWarn('tickRooms cleanup candidate changed before deletion',{code,phase:r.phase,reason,committed:deletion.committed,stillExists:deletion.snapshot.exists()});
    }
   }catch(error){
    logError('tickRooms failed to clean up room',{code,phase:r.phase,reason,error:error instanceof Error?error.message:String(error)});
   }
   continue;
  }
  const stalePlayers=Object.values(r.players).some(p=>p.device!=='shared'&&p.connected&&now-lastSeenAt(presence,p.uid,p.lastSeen)>15000);
  const staleSpectators=Object.values(r.spectators||{}).some(p=>p.connected&&now-lastSeenAt(presence,p.uid,p.lastSeen)>15000);
  const hybridSharedTerminalIsActive=sharedTerminalActive(r.settings.method,r.players,presence,now),managerStale=r.settings.method!=='shared'&&!hybridSharedTerminalIsActive&&!finished&&now-lastSeenAt(presence,managerUid(r),r.managerLastSeen||r.players[managerUid(r)]?.lastSeen)>15000;
  const discussionExpired=['discussion','execution','wordwolf-discussion','wordwolf-caught','wordwolf-guess'].includes(r.phase)&&!r.paused&&!!r.deadline&&r.deadline<=now;
  const hasOnlinePlayer=Object.values(r.players).some(p=>seen(p.uid,p));
  const needsRoomMutation=stalePlayers||staleSpectators||managerStale||discussionExpired||active&&(!hasOnlinePlayer&&!r.allDisconnectedAt||hasOnlinePlayer&&!!r.allDisconnectedAt);
  // Most rooms need no server-side transition on a given minute. Skipping the
  // root transaction avoids serializing every room and competing with live
  // votes/actions. A concurrent room deletion is normal; skip that stale index.
  if(!needsRoomMutation)continue;
  let updated:Room;
  try{updated=await mutate(code,x=>{
   advance(x,now);
   for(const p of Object.values(x.players))if(p.device!=='shared'&&p.connected&&now-lastSeenAt(presence,p.uid,p.lastSeen)>15000){p.connected=false;p.disconnectedAt=now;p.disconnectedPhase=x.phase;log(x,'disconnect',`${p.name}の切断を検知しました。`);if(managerUid(x)===p.uid)transferManager(x,now,sharedTerminalActive(x.settings.method,x.players,presence,now))}
   if(x.settings.method!=='shared'&&!sharedTerminalActive(x.settings.method,x.players,presence,now)&&!['ended','ranking'].includes(x.phase)&&now-lastSeenAt(presence,managerUid(x),x.managerLastSeen||x.players[managerUid(x)]?.lastSeen)>15000)transferManager(x,now,sharedTerminalActive(x.settings.method,x.players,presence,now));
   const connected=Object.values(x.players).some(p=>p.connected&&now-lastSeenAt(presence,p.uid,p.lastSeen)<=15000);
   if(!connected&&!['waiting','ended','ranking'].includes(x.phase)){x.allDisconnectedAt??=now;if(now-x.allDisconnectedAt>=10*60*1000)x.endedAt??=now}
   else x.allDisconnectedAt=undefined;
   maybeResolveNight(x);
  })}catch(error){if(String((error as Error)?.message||error).includes('ルームが見つかりません'))continue;throw error}
 }
});

export const disbandRoom=onCall(async q=>{
 const uid=actor(q),code=codeOf(q.data),seatUid=String(q.data?.seatUid||''),ref=db.ref(`rooms/${code}`);
 let members:Record<string,true>={[uid]:true};
 const result=await ref.transaction((raw:any)=>{
  if(!raw)return undefined;
  const room=normalize(raw as Room),sharedManagerSeat=['shared','hybrid'].includes(room.settings.method)&&!!seatUid&&room.players[seatUid]?.device==='shared'&&isManager(room,seatUid)&&(uid===room.host||uid===room.originalHost),authorized=isManager(room,uid)||uid===room.originalHost||uid===room.host||sharedManagerSeat;
  if(!authorized)return undefined;
  members=roomSignalMembers(room);
  return null;
 });
 if(!result.committed){
  const current=await ref.get();
  if(!current.exists())err('ルームが見つかりません。','not-found');
  const room=normalize(current.val() as Room),sharedManagerSeat=['shared','hybrid'].includes(room.settings.method)&&!!seatUid&&room.players[seatUid]?.device==='shared'&&isManager(room,seatUid)&&(uid===room.host||uid===room.originalHost),authorized=isManager(room,uid)||uid===room.originalHost||uid===room.host||sharedManagerSeat;
  if(!authorized){logError('disbandRoom denied',{code,phase:room.phase,authIsManager:isManager(room,uid),authIsHost:uid===room.host,authIsOriginalHost:uid===room.originalHost,requestedSeatIsSharedManager:!!sharedManagerSeat});err('このルームを解散する権限がありません。','permission-denied')}
  members=roomSignalMembers(room);
  await ref.remove();
 }
 await db.ref(`roomSignals/${code}`).transaction((current:any)=>({closedAt:Date.now(),members:{...(current?.members||{}),...members,[uid]:true}}));
 await db.ref(`roomPresence/${code}`).remove().catch(()=>{});
 return {disbanded:true};
});
